1 | /**
2 |  * evidence-export.mjs — Stop hook for TestMind AI
3 |  *
4 |  * When a repoguard-mode task finishes, automatically exports the task session
5 |  * report to bob-evidence/, named NN-short-description.md (auto-incrementing).
6 |  *
7 |  * The last assistant message is used as the report body; the filename slug is
8 |  * derived from the first meaningful heading or sentence in that message.
9 |  *
10 |  * Registered as a Stop hook in .bob/settings.json.
11 |  */
12 | 
13 | import { readdirSync, writeFileSync, mkdirSync } from "node:fs";
14 | import { join } from "node:path";
15 | 
16 | let raw = "";
17 | for await (const chunk of process.stdin) raw += chunk;
18 | 
19 | let input;
20 | try {
21 |   input = JSON.parse(raw);
22 | } catch {
23 |   process.exit(0);
24 | }
25 | 
26 | // Only export for repoguard modes
27 | let activeMode = "";
28 | try {
29 |   const { readFileSync } = await import("node:fs");
30 |   activeMode = readFileSync(".bob/current-mode", "utf8").trim().toLowerCase();
31 | } catch {
32 |   activeMode = (process.env.REPOGUARD_MODE ?? "").toLowerCase();
33 | }
34 | 
35 | const repoguardModes = [
36 |   "orchestrator", "analyzer", "fixer", "gate", "visual-agent", "reporter",
37 |   "repoguard"
38 | ];
39 | const isRepoguardMode = repoguardModes.some(m => activeMode.includes(m));
40 | 
41 | if (!isRepoguardMode) {
42 |   process.exit(0);
43 | }
44 | 
45 | const lastMessage = String(input.last_assistant_message ?? "").trim();
46 | if (!lastMessage) {
47 |   process.exit(0);
48 | }
49 | 
50 | // ── Determine next sequential number ─────────────────────────────────────────
51 | 
52 | const evidenceDir = join(input.cwd ?? ".", "bob-evidence");
53 | try {
54 |   mkdirSync(evidenceDir, { recursive: true });
55 | } catch { /* already exists */ }
56 | 
57 | let maxN = 0;
58 | try {
59 |   for (const f of readdirSync(evidenceDir)) {
60 |     const m = f.match(/^(\d+)-/);
61 |     if (m) maxN = Math.max(maxN, parseInt(m[1], 10));
62 |   }
63 | } catch { /* empty dir is fine */ }
64 | 
65 | const nextN = String(maxN + 1).padStart(2, "0");
66 | 
67 | // ── Derive a slug from the last message ──────────────────────────────────────
68 | 
69 | function toSlug(text) {
70 |   // Try first markdown heading
71 |   const headingMatch = text.match(/^#+\s+(.+)/m);
72 |   const source = headingMatch ? headingMatch[1] : text.split(/[.\n]/)[0];
73 |   return source
74 |     .toLowerCase()
75 |     .replace(/[^a-z0-9 ]/g, "")
76 |     .trim()
77 |     .replace(/\s+/g, "-")
78 |     .slice(0, 50)
79 |     .replace(/-+$/, "");
80 | }
81 | 
82 | const slug = toSlug(lastMessage) || "session";
83 | const filename = `${nextN}-${slug}.md`;
84 | const filepath = join(evidenceDir, filename);
85 | 
86 | // ── Write the evidence file ───────────────────────────────────────────────────
87 | 
88 | const timestamp = new Date().toISOString();
89 | const modeLabel = activeMode || "unknown";
90 | 
91 | const content = `# Bob Evidence — ${filename}
92 | 
93 | **Mode:** ${modeLabel}  
94 | **Exported:** ${timestamp}  
95 | **Session:** ${input.session_id ?? "unknown"}
96 | 
97 | ---
98 | 
99 | ${lastMessage}
100 | `;
101 | 
102 | try {
103 |   writeFileSync(filepath, content, "utf8");
104 |   // Print to stdout so Bob adds it as context (optional, kept brief)
105 |   process.stdout.write(`[evidence-export] Saved ${filename}\n`);
106 | } catch (err) {
107 |   // Fail open — evidence export must never break a session
108 |   process.stderr.write(`[evidence-export] Could not write ${filepath}: ${err.message}\n`);
109 | }
