"""Core measurement functions: coverage, gaps, mutation, risk, dashboard."""

from __future__ import annotations

import subprocess
import json
from pathlib import Path
from dataclasses import dataclass, field


@dataclass
class CoverageResult:
    percent: float
    covered_lines: int
    total_lines: int
    missing_lines: dict[str, list[int]] = field(default_factory=dict)


@dataclass
class GapReport:
    uncovered_functions: list[str] = field(default_factory=list)
    uncovered_files: list[str] = field(default_factory=list)
    missing_lines_by_file: dict[str, list[int]] = field(default_factory=dict)


@dataclass
class MutationResult:
    score: float
    killed: int
    survived: int
    total: int
    surviving_mutant_ids: list[int] = field(default_factory=list)


@dataclass
class RiskScore:
    file: str
    score: float  # 0.0 – 1.0
    reasons: list[str] = field(default_factory=list)


def measure_coverage(repo_path: str | Path) -> CoverageResult:
    """Run pytest with coverage on *repo_path* and return a CoverageResult."""
    repo = Path(repo_path)
    result = subprocess.run(
        ["pytest", "--cov", "--cov-report=json", "-q", "--tb=no"],
        cwd=repo,
        capture_output=True,
        text=True,
    )
    coverage_json = repo / "coverage.json"
    if not coverage_json.exists():
        return CoverageResult(percent=0.0, covered_lines=0, total_lines=0)

    data = json.loads(coverage_json.read_text())
    totals = data.get("totals", {})
    missing: dict[str, list[int]] = {}
    for fname, fdata in data.get("files", {}).items():
        if fdata.get("missing_lines"):
            missing[fname] = fdata["missing_lines"]

    return CoverageResult(
        percent=totals.get("percent_covered", 0.0),
        covered_lines=totals.get("covered_lines", 0),
        total_lines=totals.get("num_statements", 0),
        missing_lines=missing,
    )


def find_coverage_gaps(coverage: CoverageResult) -> GapReport:
    """Derive a structured gap report from a CoverageResult."""
    gap = GapReport()
    gap.missing_lines_by_file = dict(coverage.missing_lines)
    gap.uncovered_files = [f for f, lines in coverage.missing_lines.items() if lines]
    return gap


def run_mutation(
    repo_path: str | Path,
    paths_to_mutate: str = ".",
    tests_dir: str = "tests",
) -> MutationResult:
    """Run mutmut on *repo_path* and return a MutationResult."""
    repo = Path(repo_path)
    subprocess.run(
        [
            "mutmut",
            "run",
            f"--paths-to-mutate={paths_to_mutate}",
            f"--tests-dir={tests_dir}",
        ],
        cwd=repo,
        capture_output=True,
        text=True,
    )
    result_proc = subprocess.run(
        ["mutmut", "results"],
        cwd=repo,
        capture_output=True,
        text=True,
    )
    # Parse simple summary line e.g. "Killed: 42, Survived: 8, Total: 50"
    killed = survived = total = 0
    for line in result_proc.stdout.splitlines():
        lower = line.lower()
        if "killed" in lower:
            try:
                killed = int(line.split(":")[1].strip().rstrip(","))
            except (IndexError, ValueError):
                pass
        elif "survived" in lower:
            try:
                survived = int(line.split(":")[1].strip().rstrip(","))
            except (IndexError, ValueError):
                pass
        elif "total" in lower:
            try:
                total = int(line.split(":")[1].strip())
            except (IndexError, ValueError):
                pass

    score = (killed / total * 100) if total else 0.0
    return MutationResult(score=score, killed=killed, survived=survived, total=total)


def compute_risk(repo_path: str | Path, coverage: CoverageResult) -> list[RiskScore]:
    """Assign a risk score to each file based on coverage gaps and file size."""
    scores: list[RiskScore] = []
    for fname, missing in coverage.missing_lines.items():
        path = Path(repo_path) / fname
        try:
            total_lines = sum(1 for _ in path.read_text().splitlines() if _.strip())
        except OSError:
            total_lines = 1

        coverage_gap = len(missing) / max(total_lines, 1)
        risk = RiskScore(
            file=fname,
            score=round(min(coverage_gap, 1.0), 3),
            reasons=[f"{len(missing)} uncovered lines out of ~{total_lines}"],
        )
        scores.append(risk)

    scores.sort(key=lambda r: r.score, reverse=True)
    return scores


def build_dashboard_data(
    coverage: CoverageResult,
    gap: GapReport,
    mutation: MutationResult | None = None,
    risk: list[RiskScore] | None = None,
) -> dict:
    """Assemble a JSON-serialisable dict for the web dashboard."""
    return {
        "coverage": {
            "percent": coverage.percent,
            "covered_lines": coverage.covered_lines,
            "total_lines": coverage.total_lines,
        },
        "gaps": {
            "uncovered_files": gap.uncovered_files,
            "missing_lines_by_file": gap.missing_lines_by_file,
        },
        "mutation": (
            {
                "score": mutation.score,
                "killed": mutation.killed,
                "survived": mutation.survived,
                "total": mutation.total,
            }
            if mutation
            else None
        ),
        "risk": (
            [{"file": r.file, "score": r.score, "reasons": r.reasons} for r in risk]
            if risk
            else []
        ),
    }

"""Detect untested FastAPI endpoints and optionally run smoke tests."""

from __future__ import annotations

import ast
import subprocess
from pathlib import Path
from dataclasses import dataclass, field


@dataclass
class EndpointInfo:
    file: str
    function: str
    method: str
    path: str
    has_test: bool = False


def find_untested_endpoints(repo_path: str | Path) -> list[EndpointInfo]:
    """
    Walk *repo_path* for FastAPI route decorators and cross-reference against
    the test files to determine which endpoints have no test coverage.
    """
    repo = Path(repo_path)
    endpoints: list[EndpointInfo] = []

    # Collect all route-decorated functions in source files
    for py_file in repo.rglob("*.py"):
        if "test_" in py_file.name or py_file.parts[-1].startswith("test"):
            continue
        try:
            tree = ast.parse(py_file.read_text(), filename=str(py_file))
        except SyntaxError:
            continue

        for node in ast.walk(tree):
            if not isinstance(node, ast.FunctionDef):
                continue
            for decorator in node.decorator_list:
                method, route_path = _extract_route(decorator)
                if method:
                    endpoints.append(
                        EndpointInfo(
                            file=str(py_file.relative_to(repo)),
                            function=node.name,
                            method=method,
                            path=route_path or "/",
                        )
                    )

    # Mark endpoints that appear in test files
    test_bodies: list[str] = []
    for tf in repo.rglob("test_*.py"):
        try:
            test_bodies.append(tf.read_text())
        except OSError:
            pass
    combined = "\n".join(test_bodies)

    for ep in endpoints:
        if ep.function in combined or ep.path in combined:
            ep.has_test = True

    return endpoints


def _extract_route(decorator: ast.expr) -> tuple[str, str]:
    """Return (HTTP_METHOD, path) from a FastAPI route decorator node, or ('', '')."""
    http_methods = {"get", "post", "put", "patch", "delete", "head", "options"}
    if isinstance(decorator, ast.Call):
        func = decorator.func
        attr = getattr(func, "attr", None) or getattr(func, "id", None) or ""
        if attr.lower() in http_methods:
            path_arg = ""
            if decorator.args:
                arg = decorator.args[0]
                if isinstance(arg, ast.Constant):
                    path_arg = arg.value
            return attr.upper(), path_arg
    return "", ""


def run_endpoint_smoke_tests(
    base_url: str,
    endpoints: list[EndpointInfo],
) -> dict[str, dict]:
    """
    Fire a minimal HTTP request at each endpoint and return a status map.
    Requires the server to be running at *base_url*.
    """
    try:
        import httpx
    except ImportError:
        return {"error": "httpx not installed"}

    results: dict[str, dict] = {}
    with httpx.Client(base_url=base_url, timeout=5.0) as client:
        for ep in endpoints:
            key = f"{ep.method} {ep.path}"
            try:
                response = client.request(ep.method, ep.path)
                results[key] = {"status_code": response.status_code, "ok": response.is_success}
            except Exception as exc:
                results[key] = {"status_code": None, "ok": False, "error": str(exc)}

    return results

"""CLI entry point: repoguard analyze | fix | gate | serve | mcp"""

from __future__ import annotations

import json
import sys
from pathlib import Path

import click
from rich.console import Console
from rich.table import Table

console = Console()


@click.group()
def main() -> None:
    """RepoGuard — AI-powered test quality guard."""


@main.command()
@click.argument("repo_path", default=".", type=click.Path(exists=True))
@click.option("--mutation", is_flag=True, default=False, help="Also run mutation testing (slow).")
@click.option("--endpoints", is_flag=True, default=False, help="Detect untested FastAPI endpoints.")
@click.option("--json-output", is_flag=True, default=False, help="Print raw JSON instead of formatted output.")
def analyze(repo_path: str, mutation: bool, endpoints: bool, json_output: bool) -> None:
    """Measure test coverage and quality gaps in REPO_PATH."""
    from .pipeline import run_pipeline

    console.print(f"[bold cyan]Analysing[/] {repo_path} …")
    result = run_pipeline(
        repo_path,
        include_mutation=mutation,
        include_endpoints=endpoints,
    )

    if json_output:
        click.echo(json.dumps(result.dashboard, indent=2))
        return

    _print_coverage_table(result)


@main.command()
@click.argument("repo_path", default=".", type=click.Path(exists=True))
@click.option("--threshold", default=80.0, show_default=True, help="Coverage % gate threshold.")
def gate(repo_path: str, threshold: float) -> None:
    """CI gate: exit 1 if coverage is below THRESHOLD."""
    from .pipeline import run_pipeline

    result = run_pipeline(repo_path, gate_threshold=threshold)
    _print_coverage_table(result)

    if result.passed_gate:
        console.print(f"[bold green]✓ Gate passed[/] ({result.coverage.percent:.1f}% ≥ {threshold}%)")
    else:
        console.print(f"[bold red]✗ Gate failed[/] ({result.coverage.percent:.1f}% < {threshold}%)")
        sys.exit(1)


@main.command()
@click.argument("repo_path", default=".", type=click.Path(exists=True))
def fix(repo_path: str) -> None:
    """Start a Bob-driven fix loop for REPO_PATH. (Requires Bob IDE or Bob Shell.)"""
    console.print("[bold yellow]fix[/] mode is designed to be called by Bob as an MCP tool.")
